script:
// RXPower untuk Chart
let now = Date.now();
let m = "N/A";

// Function pembaca parameter spesifik secara aman
function getValue(pathList) {
  for (let p of pathList) {
    let d = declare(p, {value: now});
    if (d && d.size) {
      for (let item of d) {
        let raw = item.value ? (Array.isArray(item.value) ? item.value[0] : item.value) : null;
        if (raw !== undefined && raw !== null && raw !== "") {
          let num = Number(raw);
          if (!isNaN(num) && num !== 0) return num;
        }
      }
    }
  }
  return null;
}

// 1. Parameter Khusus Perangkat Anda (Clink, HSGQ, Huawei, H1s-3, VSOL, Zimmlink)
let eponRx = getValue([
  "InternetGatewayDevice.WANDevice.*.X_CT-COM_EponInterfaceConfig.RXPower",  // Clink, VSOL EPON, Zimmlink
  "InternetGatewayDevice.WANDevice.*.X_CMCC_EponInterfaceConfig.RXPower"   // H1s-3
]);

let gponRx = getValue([
  "InternetGatewayDevice.WANDevice.*.X_GponInterafceConfig.RXPower",       // HSGQ & Huawei (typo 'Interafce')
  "InternetGatewayDevice.WANDevice.*.X_CT-COM_GponInterfaceConfig.RXPower"  // VSOL GPON
]);

let eponTx = getValue([
  "InternetGatewayDevice.WANDevice.*.X_CT-COM_EponInterfaceConfig.TXPower"   // Backup EPON
]);

let calcVal = null;
let num = eponRx !== null ? eponRx : gponRx;

// 2. Kalkulasi Presisi
if (num !== null && num < 0 && num > -100) {
  calcVal = num;
}
else if (eponRx !== null && eponRx >= 5 && eponRx <= 999) {
  calcVal = 10 * Math.log10(eponRx / 1000) - 10.0;
}
else if (gponRx !== null && gponRx >= 5 && gponRx <= 999) {
  calcVal = 10 * Math.log10(gponRx / 1000) - 9.0;
}
else if (num !== null) {
  if (num <= -5000 && num >= -40000) calcVal = num / 1000;
  else if (num >= 5000 && num <= 40000) calcVal = -num / 1000;
  else if (num <= -1000 && num >= -5000) calcVal = num / 100;
  else if (num >= 1000 && num <= 5000) calcVal = -num / 100;
  else if (num >= 10000 && num <= 30000) calcVal = 10 * Math.log10(num / 10000) - 25.4;
  else if (num > 30000) calcVal = (num - 65536) / 100;
}
else if (eponTx !== null && eponTx >= 10000 && eponTx <= 30000) {
  calcVal = 10 * Math.log10(eponTx / 10000) - 25.4;
}

// 3. Format Angka Desimal Murni (Tanpa " dBm")
if (calcVal !== null && calcVal <= -5 && calcVal >= -38) {
  m = (Math.ceil(calcVal * 100) / 100).toString(); // Menghasilkan string angka murni (misal "-14.74")
}

return {
  writable: false, 
  value: [m, "xsd:string"]
};

// Informasi IP WAN
let ipAddress = "";

// 1. Cek lewat jalur TR-181 (Device.IP.Interface...)
let tr181Paths = [
  "Device.IP.Interface.5.IPv4Address.1.IPAddress",
  "Device.IP.Interface.6.IPv4Address.1.IPAddress"
  // Jika ada interface lain, bisa ditambahkan di sini, contoh:
  // "Device.IP.Interface.3.IPv4Address.1.IPAddress"
];

for (let i = 0; i < tr181Paths.length; i++) {
  let res = declare(tr181Paths[i], {value: Date.now()});
  if (res.size && res.value[0]) {
    let val = String(res.value[0]).trim();
    if (val && val !== "0.0.0.0" && val !== "N/A" && val !== "") {
      ipAddress = val;
      break;
    }
  }
}

// 2. Jika belum ketemu, cek jalur WANIPConnection (TR-098 lama, difilter STATIC)
if (!ipAddress) {
  let ipPaths = [
    "InternetGatewayDevice.WANDevice.1.WANConnectionDevice.1.WANIPConnection.1",
    "InternetGatewayDevice.WANDevice.1.WANConnectionDevice.2.WANIPConnection.1",
    "InternetGatewayDevice.WANDevice.1.WANConnectionDevice.3.WANIPConnection.1",
    "InternetGatewayDevice.WANDevice.1.WANConnectionDevice.4.WANIPConnection.1"
  ];

  for (let j = 0; j < ipPaths.length; j++) {
    let basePath = ipPaths[j];
    let typeRes = declare(basePath + ".AddressingType", {value: Date.now()});
    if (typeRes.size && typeRes.value[0]) {
      let connType = String(typeRes.value[0]).trim().toUpperCase();
      if (connType === "STATIC") {
        let ipRes = declare(basePath + ".ExternalIPAddress", {value: Date.now()});
        if (ipRes.size && ipRes.value[0]) {
          let val = String(ipRes.value[0]).trim();
          if (val && val !== "0.0.0.0" && val !== "N/A" && val !== "") {
            ipAddress = val;
            break; 
          }
        }
      }
    }
  }
}

// 3. Jika masih belum ketemu, cek jalur WANPPPConnection (PPPoE)
if (!ipAddress) {
  let pppPaths = [
    "InternetGatewayDevice.WANDevice.1.WANConnectionDevice.1.WANPPPConnection.1",
    "InternetGatewayDevice.WANDevice.1.WANConnectionDevice.2.WANPPPConnection.1",
    "InternetGatewayDevice.WANDevice.1.WANConnectionDevice.3.WANPPPConnection.1",
    "InternetGatewayDevice.WANDevice.1.WANConnectionDevice.4.WANPPPConnection.1",
  ];

  for (let k = 0; k < pppPaths.length; k++) {
    let pppBasePath = pppPaths[k];
    let pppIpRes = declare(pppBasePath + ".ExternalIPAddress", {value: Date.now()});
    if (pppIpRes.size && pppIpRes.value[0]) {
      let val = String(pppIpRes.value[0]).trim();
      if (val && val !== "0.0.0.0" && val !== "N/A" && val !== "") {
        ipAddress = val;
        break;
      }
    }
  }
}

// Jika tidak ada satupun yang ketemu
if (!ipAddress) {
  ipAddress = "-";
}

return {writable: false, value: [ipAddress, "xsd:string"]};

// NOte
let value;
if ("value" in args[1]) {
    // Dipakai saat Anda mengedit/memasukkan nilai baru dari UI
    value = args[1].value;
} else if ("value" in args[3]) {
    // Mempertahankan nilai lama yang sudah tersimpan di database saat di-summon/refresh
    value = args[3].value;
} else {
    // Nilai default jika belum ada isi sama sekali
    value = ['', 'xsd:string'];
}

return {writable: true, value: value};

// Informasi Temperature 
let tempPaths = [
  // Vendor CMCC (China Mobile)
  "InternetGatewayDevice.WANDevice.1.X_CMCC_EponInterfaceConfig.TransceiverTemperature",
  "InternetGatewayDevice.WANDevice.1.X_CMCC_GponInterfaceConfig.TransceiverTemperature",

  // Vendor CT-COM & Generic GPON/EPON
  "InternetGatewayDevice.WANDevice.1.X_CT-COM_EponInterfaceConfig.TransceiverTemperature",
  "InternetGatewayDevice.WANDevice.1.X_CT-COM_GponInterfaceConfig.TransceiverTemperature",
  "InternetGatewayDevice.WANDevice.1.X_GponInterafceConfig.TransceiverTemperature",
  "InternetGatewayDevice.WANDevice.1.X_GponInterfaceConfig.TransceiverTemperature"

  // Router Biasa Ruijie, TotoLink 

];

let rawTemp = null;

for (let path of tempPaths) {
  let d = declare(path, {value: Date.now()});
  if (d && d.value && d.value.length > 0) {
    let val = Number(d.value[0]);
    if (!isNaN(val) && val !== 0) {
      rawTemp = val;
      break;
    }
  }
}

if (rawTemp !== null && !isNaN(rawTemp) && rawTemp !== 0) {
  let finalTemp = rawTemp;

  // 1. Format SFF-8472 / CMCC / ZTE (contoh: 6973 -> 27.24 °C, 11775 -> 45.99 °C)
  if (finalTemp > 5000) {
    finalTemp = finalTemp / 256;
  } 
  // 2. Nilai Mentah dikali 100 (contoh: 4250 -> 42.50 °C)
  else if (finalTemp > 1000) {
    finalTemp = finalTemp / 100;
  } 
  // 3. Firmware HSGQ / Realtek (contoh: 129 -> 43.00 °C)
  else if (finalTemp > 100) {
    finalTemp = finalTemp / 3;
  }

  return {
    type: "string",
    value: finalTemp.toFixed(2) + " °C",
    writable: false
  };
}

return {
  type: "string",
  value: "N/A",
  writable: false
};

// UptimeDevice
let uptimeSeconds = null;

// 1. Ambil nilai UpTime terbaru dari IGD (TR-069)
let igdUpTime = declare("InternetGatewayDevice.DeviceInfo.UpTime", {value: Date.now()});

if (igdUpTime && igdUpTime.value && igdUpTime.value.length > 0) {
  uptimeSeconds = igdUpTime.value[0];
} else {
  // 2. Fallback ke TR-181 (Device)
  let devUpTime = declare("Device.DeviceInfo.UpTime", {value: Date.now()});
  if (devUpTime && devUpTime.value && devUpTime.value.length > 0) {
    uptimeSeconds = devUpTime.value[0];
  }
}

// Jika belum ada nilai di database local
if (uptimeSeconds === null || uptimeSeconds === undefined || uptimeSeconds === "") {
  return {type: "string", value: "-", writable: false};
}

let sec = parseInt(uptimeSeconds, 10);
if (isNaN(sec)) return {type: "string", value: "-", writable: false};

// Kalkulasi Hari, Jam, Menit, dan Detik
let days = Math.floor(sec / 86400);
let hours = Math.floor((sec % 86400) / 3600);
let minutes = Math.floor((sec % 3600) / 60);
//let seconds = sec % 60; // <--- Menghitung sisa detik

let parts = [];
if (days > 0) parts.push(days + "d");
if (hours > 0 || days > 0) parts.push(hours + "h");
if (minutes > 0 || hours > 0 || days > 0) parts.push(minutes + "m");
//parts.push(seconds + "s"); // <--- Menambahkan detik ke hasil tampilan

return {type: "string", value: parts.join(" "), writable: false};

// VP writable: captcha login web (CF_WEB_CAPTCHA) pada ONT VSOL V2801RGW.
// Flag ini tidak diekspos lewat TR-069 dan tidak punya form web, jadi nilainya
// dibaca dari boaform custom_page dan ditulis dengan upload running-config yang
// sudah ditambal (ext ont_captcha). Efeknya langsung tanpa reboot.
// ext() sengaja tidak dibungkus try/catch: ia melempar simbol agar sesi di-restart.
const now = Date.now();

const pc = declare("InternetGatewayDevice.DeviceInfo.ProductClass", { value: now });
if (!pc || !pc.value || String(pc.value[0]) !== "V2801RGW")
  return { writable: false, value: ["[hanya V2801RGW]", "xsd:string"] };

const url = declare("VirtualParameters.IPTR069", { value: now });
const ip = url && url.value && url.value[0]
  ? String(url.value[0]).replace(/^https?:\/\//, "").replace(/\/.*$/, "")
  : "";

if (!/^[0-9.]+$/.test(ip))
  return { writable: true, value: ["[IP ONT tidak diketahui]", "xsd:string"] };

const set = args && args[1] && args[1].value ? String(args[1].value[0]).trim() : null;

if (set != null && set.length) {
  // Nilai yang dikembalikan beda dari yang diminta membuat GenieACS loop commit
  // (fault too_many_commits), jadi penolakan dilakukan dengan melempar error.
  if (set !== "0" && set !== "1") throw new Error("Captcha hanya menerima nilai 0 atau 1");
  // Upload running-config ke flash butuh ~2,2 d; GENIEACS_EXT_TIMEOUT bawaan 3 d.
  const msg = ext("ont_captcha", "set", ip, set, 2600);
  if (msg !== "OK") throw new Error("Gagal mengatur captcha: " + msg);
  return { writable: true, value: [set, "xsd:string"] };
}

const raw = ext("ont_captcha", "get", ip, 1500);
if (!raw) return { writable: true, value: ["[ext tidak mengembalikan data]", "xsd:string"] };

let f = null;
try {
  f = JSON.parse(raw);
} catch (e) {
  return { writable: true, value: ["[respon ext tidak valid]", "xsd:string"] };
}

if (f.captcha !== "0" && f.captcha !== "1")
  return { writable: true, value: ["[captcha tidak terbaca]", "xsd:string"] };

return { writable: true, value: [f.captcha, "xsd:string"] };

// Informasi Epon, Gpon dan Ethernet
let pon = "";

// 1. Coba ambil dari AccessType
let v1 = declare("InternetGatewayDevice.DeviceInfo.AccessType", {value: Date.now()});
if (v1.size && v1.value[0]) {
  pon = v1.value[0];
}

// 2. Jika kosong, coba ambil dari WANAccessType
if (!pon) {
  let v2 = declare("InternetGatewayDevice.WANDevice.1.WANCommonInterfaceConfig.WANAccessType", {value: Date.now()});
  if (v2.size && v2.value[0]) {
    pon = v2.value[0];
  }
}

// 3. Ubah ke huruf besar untuk standarisasi
let checkPon = String(pon).toUpperCase();

// 4. Jika isinya PPPOE atau kosong, jadikan "Ethernet"
if (!pon || checkPon.includes("PPPOE")) {
  pon = "Ethernet";
} else {
  // Jika tidak kosong/PPPOE, pastikan hasilnya konsisten huruf besar (GPON, EPON, dll)
  pon = checkPon;
}

return {writable: false, value: [pon, "xsd:string"]};

// VP writable: username akun superadmin (SUSER_NAME) pada ONT VSOL V2801RGW.
// Firmware tidak mengekspos akun web lewat TR-069, jadi nilainya dibaca dari
// running-config dan ditulis lewat ext ont_account (boaform). IP diambil dari VP IPTR069.
// ext() sengaja tidak dibungkus try/catch: ia melempar simbol agar sesi di-restart.
const now = Date.now();

const pc = declare("InternetGatewayDevice.DeviceInfo.ProductClass", { value: now });
if (!pc || !pc.value || String(pc.value[0]) !== "V2801RGW")
  return { writable: false, value: ["[hanya V2801RGW]", "xsd:string"] };

const url = declare("VirtualParameters.IPTR069", { value: now });
const ip = url && url.value && url.value[0]
  ? String(url.value[0]).replace(/^https?:\/\//, "").replace(/\/.*$/, "")
  : "";

if (!/^[0-9.]+$/.test(ip))
  return { writable: true, value: ["[IP ONT tidak diketahui]", "xsd:string"] };

const set = args && args[1] && args[1].value ? String(args[1].value[0]).trim() : null;

if (set != null && set.length) {
  // Nilai yang dikembalikan beda dari yang diminta membuat GenieACS loop commit
  // (fault too_many_commits), jadi penolakan dilakukan dengan melempar error.
  const msg = ext("ont_account", "setName", ip, "admin", set, 2800);
  if (msg !== "OK") throw new Error("Username superadmin gagal diganti: " + msg);
  return { writable: true, value: [set, "xsd:string"] };
}

const raw = ext("ont_account", "get", ip, 1500);
if (!raw) return { writable: true, value: ["[ext tidak mengembalikan data]", "xsd:string"] };

let a = null;
try {
  a = JSON.parse(raw);
} catch (e) {
  return { writable: true, value: ["[respon ext tidak valid]", "xsd:string"] };
}

const val = String(a.adminName || "");
if (!val.length) return { writable: true, value: ["[Username superadmin tidak terbaca]", "xsd:string"] };
return { writable: true, value: [val, "xsd:string"] };

// 1. Ambil IP dari koneksi WAN bertipe DHCP
let ipDHCP = declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANIPConnection.[AddressingType:DHCP].ExternalIPAddress", {value: 1});

if (ipDHCP && ipDHCP.value && ipDHCP.value[0]) {
  let val = ipDHCP.value[0];
  if (val && val !== "0.0.0.0" && val !== "N/A" && val !== "") {
    return {type: "string", value: "http://" + val, writable: false};
  }
}

// 2. Ambil IP dari koneksi WAN PPPoE (Tambahan baru)
let ipPPPoE = declare("InternetGatewayDevice.WANDevice.1.WANConnectionDevice.1.WANPPPConnection.1.ExternalIPAddress", {value: 1});

if (ipPPPoE && ipPPPoE.value && ipPPPoE.value[0]) {
  let val = ipPPPoE.value[0];
  if (val && val !== "0.0.0.0" && val !== "N/A" && val !== "") {
    return {type: "string", value: "http://" + val, writable: false};
  }
}

// 3. Fallback TR-181 (Interface 5)
let ipTR181_5 = declare("Device.IP.Interface.5.IPv4Address.1.IPAddress", {value: 1});

if (ipTR181_5 && ipTR181_5.value && ipTR181_5.value[0]) {
  let val = ipTR181_5.value[0];
  if (val && val !== "0.0.0.0" && val !== "N/A" && val !== "") {
    return {type: "string", value: "http://" + val, writable: false};
  }
}

// 4. Fallback TR-181 (Interface 6) - TAMBAHAN BARU
let ipTR181_6 = declare("Device.IP.Interface.6.IPv4Address.1.IPAddress", {value: 1});

if (ipTR181_6 && ipTR181_6.value && ipTR181_6.value[0]) {
  let val = ipTR181_6.value[0];
  if (val && val !== "0.0.0.0" && val !== "N/A" && val !== "") {
    return {type: "string", value: "http://" + val, writable: false};
  }
}

// Default jika IP belum terdeteksi
return {type: "string", value: "", writable: false};

// VP writable: password akun normal user (USER_PASSWORD) pada ONT VSOL V2801RGW.
// Firmware tidak mengekspos akun web lewat TR-069, jadi nilainya dibaca dari
// running-config dan ditulis lewat ext ont_account (boaform). IP diambil dari VP IPTR069.
// ext() sengaja tidak dibungkus try/catch: ia melempar simbol agar sesi di-restart.
const now = Date.now();

const pc = declare("InternetGatewayDevice.DeviceInfo.ProductClass", { value: now });
if (!pc || !pc.value || String(pc.value[0]) !== "V2801RGW")
  return { writable: false, value: ["[hanya V2801RGW]", "xsd:string"] };

const url = declare("VirtualParameters.IPTR069", { value: now });
const ip = url && url.value && url.value[0]
  ? String(url.value[0]).replace(/^https?:\/\//, "").replace(/\/.*$/, "")
  : "";

if (!/^[0-9.]+$/.test(ip))
  return { writable: true, value: ["[IP ONT tidak diketahui]", "xsd:string"] };

const set = args && args[1] && args[1].value ? String(args[1].value[0]).trim() : null;

if (set != null && set.length) {
  // Nilai yang dikembalikan beda dari yang diminta membuat GenieACS loop commit
  // (fault too_many_commits), jadi penolakan dilakukan dengan melempar error.
  const msg = ext("ont_account", "setPass", ip, "user", set, "", 2800);
  if (msg !== "OK") throw new Error("Password normal user gagal diganti: " + msg);
  return { writable: true, value: [set, "xsd:string"] };
}

const raw = ext("ont_account", "get", ip, 1500);
if (!raw) return { writable: true, value: ["[ext tidak mengembalikan data]", "xsd:string"] };

let a = null;
try {
  a = JSON.parse(raw);
} catch (e) {
  return { writable: true, value: ["[respon ext tidak valid]", "xsd:string"] };
}

const val = String(a.userPass || "");
if (!val.length) return { writable: true, value: ["[Password normal user tidak terbaca]", "xsd:string"] };
return { writable: true, value: [val, "xsd:string"] };

// VP writable: username akun normal user (USER_NAME) pada ONT VSOL V2801RGW.
// Firmware tidak mengekspos akun web lewat TR-069, jadi nilainya dibaca dari
// running-config dan ditulis lewat ext ont_account (boaform). IP diambil dari VP IPTR069.
// ext() sengaja tidak dibungkus try/catch: ia melempar simbol agar sesi di-restart.
const now = Date.now();

const pc = declare("InternetGatewayDevice.DeviceInfo.ProductClass", { value: now });
if (!pc || !pc.value || String(pc.value[0]) !== "V2801RGW")
  return { writable: false, value: ["[hanya V2801RGW]", "xsd:string"] };

const url = declare("VirtualParameters.IPTR069", { value: now });
const ip = url && url.value && url.value[0]
  ? String(url.value[0]).replace(/^https?:\/\//, "").replace(/\/.*$/, "")
  : "";

if (!/^[0-9.]+$/.test(ip))
  return { writable: true, value: ["[IP ONT tidak diketahui]", "xsd:string"] };

const set = args && args[1] && args[1].value ? String(args[1].value[0]).trim() : null;

if (set != null && set.length) {
  // Nilai yang dikembalikan beda dari yang diminta membuat GenieACS loop commit
  // (fault too_many_commits), jadi penolakan dilakukan dengan melempar error.
  const msg = ext("ont_account", "setName", ip, "user", set, 2800);
  if (msg !== "OK") throw new Error("Username normal user gagal diganti: " + msg);
  return { writable: true, value: [set, "xsd:string"] };
}

const raw = ext("ont_account", "get", ip, 1500);
if (!raw) return { writable: true, value: ["[ext tidak mengembalikan data]", "xsd:string"] };

let a = null;
try {
  a = JSON.parse(raw);
} catch (e) {
  return { writable: true, value: ["[respon ext tidak valid]", "xsd:string"] };
}

const val = String(a.userName || "");
if (!val.length) return { writable: true, value: ["[Username normal user tidak terbaca]", "xsd:string"] };
return { writable: true, value: [val, "xsd:string"] };

// Memanggil MikroTikComment
let targetIp = "";

// 1. Pindai IP WAN PPPoE
let pppConn = declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.ExternalIPAddress", {value: 1});
for (let p of pppConn) {
  if (p.value && p.value[0] && p.value[0] !== "0.0.0.0" && p.value[0] !== "") {
    targetIp = p.value[0];
    break;
  }
}

// 2. Pindai IP WAN Static / DHCP
if (!targetIp) {
  let wanConn = declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANIPConnection.*.ExternalIPAddress", {value: 1});
  for (let p of wanConn) {
    if (p.value && p.value[0] && p.value[0] !== "0.0.0.0" && p.value[0] !== "") {
      targetIp = p.value[0];
      break;
    }
  }
}

// 3. Pindai IP TR-181 (WAN Connection PPPoE lama)
if (!targetIp) {
  let tr181 = declare("InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.ExternalIPAddress", {value: 1});
  for (let p of tr181) {
    if (p.value && p.value[0] && p.value[0] !== "0.0.0.0" && p.value[0] !== "127.0.0.1" && p.value[0] !== "") {
      targetIp = p.value[0];
      break;
    }
  }
}

// =========================================================================
// 3.5. Pindai Spesifik Interface 6 dan 5 (TR-181) dengan {value: 1} & 10.26.
// =========================================================================
if (!targetIp) {
  let specificPaths = [
    "Device.IP.Interface.6.IPv4Address.1.IPAddress",
    "Device.IP.Interface.5.IPv4Address.1.IPAddress"
  ];

  for (let path of specificPaths) {
    let tr181 = declare(path, {value: 1});
    for (let p of tr181) {
      if (p.value && p.value[0]) {
        let val = p.value[0];
        if (val !== "0.0.0.0" && val !== "127.0.0.1" && val !== "" && val.startsWith("10.26.")) {
          targetIp = val;
          break;
        }
      }
    }
    if (targetIp) break;
  }
}

// 4. Pindai IP TR-181 Multi-Interface dengan filter khusus awalan "10.26."
if (!targetIp) {
  let tr181 = declare("Device.IP.Interface.*.IPv4Address.*.IPAddress", {value: 1});
  for (let p of tr181) {
    if (p.value && p.value[0]) {
      let val = p.value[0];
      if (val !== "0.0.0.0" && val !== "127.0.0.1" && val !== "" && val.startsWith("10.26.")) {
        targetIp = val;
        break;
      }
    }
  }
}

// 5. Fallback ConnectionRequestURL
if (!targetIp) {
  let connUrl = declare("InternetGatewayDevice.ManagementServer.ConnectionRequestURL", {value: 1});
  if (!connUrl.value || !connUrl.value[0]) {
    connUrl = declare("Device.ManagementServer.ConnectionRequestURL", {value: 1});
  }
  if (connUrl.value && connUrl.value[0]) {
    let match = connUrl.value[0].match(/https?:\/\/([^:\/]+)/);
    if (match && match[1] && match[1] !== "0.0.0.0") {
      targetIp = match[1];
    }
  }
}

if (!targetIp) {
  return {writable: false, value: ["IP Not Found", "xsd:string"]};
}

// Panggil extension mikrotik
let comment = "";
try {
  comment = ext("mikrotik", "getComment", targetIp);
} catch (e) {
  comment = "";
}

// =========================================================================
// ISOLASI TRY-CATCH UNTUK TAG
// =========================================================================
if (comment && typeof comment === "string" && comment !== "IP Tidak Ada di Queue" && comment !== "Comment Kosong" && !comment.startsWith("Error") && !comment.startsWith("HTTP")) {

  try {
    let cleanTagName = comment.replace(/[\/\s\(\)\.\,\\]+/g, "_").replace(/[^a-zA-Z0-9_\-]/g, "");
    if (cleanTagName) {
      declare("Tags." + cleanTagName, null, {value: true});
    }
  } catch (err) {
    // Biarkan kosong jika penambahan tag gagal
  }

  return {writable: false, value: [comment, "xsd:string"]};
}

return {writable: false, value: [targetIp, "xsd:string"]};

// RSSI tiap klien WiFi yang ter-asosiasi pada ONT.
// Sumber 1: TR-069  X_HW_RSSI (firmware baru) -> SignalStrength (TR-098)
// Sumber 2: web API boaform ONT via ext("ont_wifi","get",ip) untuk firmware lama
//           yang tidak mengekspos RSSI sama sekali lewat TR-069.
// Nama klien diambil dari tabel hosts TR-069: LANDevice.1.Hosts.Host.*.HostName
// Output: "OPPO-A98-5G (192.168.1.3):-28 dBm, 192.168.1.11:-33 dBm" (terburuk lebih dulu)
const now = Date.now();

function attrs(entry) {
  return Array.isArray(entry) ? entry[1] : entry;
}

function entryPath(entry) {
  return Array.isArray(entry) ? entry[0] || "" : entry.path || "";
}

function entryValue(entry) {
  const a = attrs(entry);
  if (!a || a.value == null) return null;
  const v = Array.isArray(a.value) ? a.value[0] : a.value;
  return Array.isArray(v) ? v[0] : v;
}

function declareList(path) {
  const res = [];
  const d = declare(path, { value: now });
  if (!d || !d.size) return res;
  for (const entry of d) {
    const value = entryValue(entry);
    if (value == null || value === "") continue;
    const path2 = entryPath(entry);
    res.push({ path: path2, inst: path2.replace(/\.[^.]*$/, ""), value: value });
  }
  return res;
}

const normMac = (v) => String(v).toUpperCase().replace(/[^0-9A-F]/g, "");

const WLAN = "InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.AssociatedDevice.*.";
const readClients = (paramName) => declareList(WLAN + paramName);

function result(text) {
  return { writable: false, value: [text, "xsd:string"] };
}

// Instansi AssociatedDevice -> label IP (fallback: MAC)
function labelsByInst(candidates) {
  const m = new Map();
  for (const p of candidates) {
    for (const c of readClients(p)) {
      if (!c.inst || m.has(c.inst)) continue;
      const v = String(c.value).trim();
      if (v && v !== "0.0.0.0") m.set(c.inst, v);
    }
  }
  return m;
}

// HostName klien LAN dari tabel hosts, diindex per IP dan per MAC.
function hostIndex() {
  const H = "InternetGatewayDevice.LANDevice.*.Hosts.Host.*.";
  const nameByInst = new Map();
  for (const e of declareList(H + "HostName")) {
    const nm = String(e.value).trim();
    if (nm) nameByInst.set(e.inst, nm);
  }
  const byIp = new Map();
  const byMac = new Map();
  for (const e of declareList(H + "IPAddress")) {
    const nm = nameByInst.get(e.inst);
    if (nm) byIp.set(String(e.value).trim(), nm);
  }
  for (const e of declareList(H + "MACAddress")) {
    const nm = nameByInst.get(e.inst);
    if (nm) byMac.set(normMac(e.value), nm);
  }
  return { byIp: byIp, byMac: byMac };
}

// Jadi "HostName (ip)" bila hostname diketahui; label bisa IP atau MAC.
function named(label, hosts) {
  const s = String(label || "").trim();
  if (!s) return "";
  const nm = hosts.byIp.get(s) || (s.indexOf(":") >= 0 ? hosts.byMac.get(normMac(s)) : null);
  return nm ? nm + " (" + s + ")" : s;
}

// ---------- 1. lewat TR-069 ----------
let clients = readClients("X_HW_RSSI");
if (!clients.length) clients = readClients("SignalStrength");

const rows = [];
for (const c of clients) {
  const rssi = Number(c.value);
  if (!isFinite(rssi) || rssi === 0) continue; // 0 dBm biasanya berarti tidak didukung
  rows.push({ inst: c.inst, rssi: rssi });
}

if (rows.length) {
  let labels = labelsByInst(["AssociatedDeviceIPAddress", "IPAddress"]);
  if (!labels.size) labels = labelsByInst(["AssociatedDeviceMACAddress", "MACAddress"]);
  const hosts = hostIndex();
  rows.sort((a, b) => a.rssi - b.rssi);
  return result(
    rows
      .map((r, i) => {
        const who = named(labels.get(r.inst), hosts) || "klien" + (i + 1);
        return who + ":" + r.rssi + " dBm";
      })
      .join(", ")
  );
}

// ---------- 2. fallback: scrape web API ONT ----------
// IP manajemen diambil dari koneksi WAN; yang bertanda TR069 dicoba lebih dulu.
function wanCandidates() {
  const ips = declareList(
    "InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANIPConnection.*.ExternalIPAddress"
  );
  if (!ips.length) return [];
  const svc = new Map();
  for (const c of declareList(
    "InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANIPConnection.*.X_CT-COM_ServiceList"
  )) {
    svc.set(c.inst, String(c.value).toUpperCase());
  }
  const out = [];
  for (const c of ips) {
    const ip = String(c.value).trim();
    if (!ip || ip === "0.0.0.0" || ip === "N/A") continue;
    out.push({ ip: ip, tr069: (svc.get(c.inst) || "").indexOf("TR069") >= 0 });
  }
  out.sort((a, b) => (a.tr069 === b.tr069 ? 0 : a.tr069 ? -1 : 1));
  // Maksimal 2 kandidat agar total waktu tetap di bawah EXT_TIMEOUT (3000 ms)
  return out.slice(0, 2);
}

// MAC -> IP klien dari cache TR-069, biar labelnya IP dan bukan MAC acak
function macToIp() {
  const ipByInst = labelsByInst(["AssociatedDeviceIPAddress"]);
  const m = new Map();
  for (const c of readClients("AssociatedDeviceMACAddress")) {
    const ip = ipByInst.get(c.inst);
    if (ip) m.set(normMac(c.value), ip);
  }
  return m;
}

let scraped = null;
let lastErr = null;
for (const cand of wanCandidates()) {
  try {
    const raw = ext("ont_wifi", "get", cand.ip, 1200);
    if (raw) {
      scraped = JSON.parse(raw);
      if (scraped.length) break;
    }
  } catch (err) {
    lastErr = err;
  }
}

if (!scraped || !scraped.length) {
  // Bedakan "memang tidak ada klien" dengan "klien ada tapi RSSI tidak terbaca"
  let total = 0;
  for (const c of declareList(
    "InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.TotalAssociations"
  )) {
    const v = Number(c.value);
    if (isFinite(v)) total += v;
  }
  let msg = total > 0 ? "RSSI tidak tersedia (" + total + " klien)" : "tidak ada klien";
  msg += lastErr ? " [ext: " + (lastErr.message || lastErr) + "]" : " [IP ONT tidak diketahui]";
  return result(msg);
}

const byMac = macToIp();
const hosts = hostIndex();
const out = [];
for (const c of scraped) {
  const rssi = Number(c.rssi);
  if (!isFinite(rssi) || rssi === 0) continue;
  const mac = normMac(c.mac);
  const label = byMac.get(mac) || String(c.ip || "").trim() || c.mac;
  out.push({ who: named(label, hosts), rssi: rssi });
}
out.sort((a, b) => a.rssi - b.rssi);
return result(
  out.map((r, i) => (r.who || "klien" + (i + 1)) + ":" + r.rssi + " dBm").join(", ")
);

// RXPower Presisi
let now = Date.now();
let rxValue = "N/A";

// Fungsi pembaca parameter presisi dengan wildcard index (.*.)
function getValue(pathList) {
  for (let p of pathList) {
    let d = declare(p, {value: now});
    if (d && d.size) {
      for (let item of d) {
        let raw = item.value ? (Array.isArray(item.value) ? item.value[0] : item.value) : null;
        if (raw !== undefined && raw !== null && raw !== "") {
          let num = Number(raw);
          if (!isNaN(num) && num !== 0) return num;
        }
      }
    }
  }
  return null;
}

// =========================================================================
// 1. PARAMETER SESUAI DAFTAR PERSIS DARI CATATAN ANDA
// =========================================================================

// EPON RX (clink, H1s-3, VsolEpon & zimmlink)
let eponRx = getValue([
  "InternetGatewayDevice.WANDevice.*.X_CT-COM_EponInterfaceConfig.RXPower",  // clink, VsolEpon & zimmlink
  "InternetGatewayDevice.WANDevice.*.X_CMCC_EponInterfaceConfig.RXPower"   // H1s-3
]);

// GPON RX (hsgq, Huawei, VsolGpon)
let gponRx = getValue([
  "InternetGatewayDevice.WANDevice.*.X_GponInterafceConfig.RXPower",       // hsgq & Huawei (typo 'Interafce')
  "InternetGatewayDevice.WANDevice.*.X_CT-COM_GponInterfaceConfig.RXPower"  // VsolGpon
]);

// Backup EPON TX
let eponTx = getValue([
  "InternetGatewayDevice.WANDevice.*.X_CT-COM_EponInterfaceConfig.TXPower"
]);

let calcVal = null;
let num = eponRx !== null ? eponRx : gponRx;

// =========================================================================
// 2. KALKULASI LOGIKA PRESISI
// =========================================================================

// PRIORITAS 1: Jika modem langsung mengirim angka minus (-19, -16)
if (num !== null && num < 0 && num > -100) {
  calcVal = num;
}
// PRIORITAS 2: Mentah positif ratusan (V-SOL EPON/GPON, H1s-3 seperti 336)
else if (eponRx !== null && eponRx >= 5 && eponRx <= 999) {
  calcVal = 10 * Math.log10(eponRx / 1000) - 10.0;
}
else if (gponRx !== null && gponRx >= 5 && gponRx <= 999) {
  calcVal = 10 * Math.log10(gponRx / 1000) - 9.0;
}
// PRIORITAS 3: Format Ribuan / Puluhan Ribu (HSGQ, Huawei, dll)
else if (num !== null) {
  if (num <= -5000 && num >= -40000) {
    calcVal = num / 1000;
  }
  else if (num >= 5000 && num <= 40000) {
    calcVal = -num / 1000;
  }
  else if (num <= -1000 && num >= -5000) {
    calcVal = num / 100;
  }
  else if (num >= 1000 && num <= 5000) {
    calcVal = -num / 100;
  }
  else if (num >= 10000 && num <= 30000) {
    calcVal = 10 * Math.log10(num / 10000) - 25.4;
  }
  else if (num > 30000) {
    calcVal = (num - 65536) / 100;
  }
}
// PRIORITAS 4: Backup mentah TX
else if (eponTx !== null && eponTx >= 10000 && eponTx <= 30000) {
  calcVal = 10 * Math.log10(eponTx / 10000) - 25.4;
}

// Format hasil akhir
if (calcVal !== null && calcVal <= -5 && calcVal >= -38) {
  rxValue = calcVal.toFixed(2) + " dBm";
}

return {
  writable: false, 
  value: [rxValue, "xsd:string"]
};

// VP writable: password akun superadmin (SUSER_PASSWORD) pada ONT VSOL V2801RGW.
// Firmware tidak mengekspos akun web lewat TR-069, jadi nilainya dibaca dari
// running-config dan ditulis lewat ext ont_account (boaform). IP diambil dari VP IPTR069.
// ext() sengaja tidak dibungkus try/catch: ia melempar simbol agar sesi di-restart.
const now = Date.now();

const pc = declare("InternetGatewayDevice.DeviceInfo.ProductClass", { value: now });
if (!pc || !pc.value || String(pc.value[0]) !== "V2801RGW")
  return { writable: false, value: ["[hanya V2801RGW]", "xsd:string"] };

const url = declare("VirtualParameters.IPTR069", { value: now });
const ip = url && url.value && url.value[0]
  ? String(url.value[0]).replace(/^https?:\/\//, "").replace(/\/.*$/, "")
  : "";

if (!/^[0-9.]+$/.test(ip))
  return { writable: true, value: ["[IP ONT tidak diketahui]", "xsd:string"] };

const set = args && args[1] && args[1].value ? String(args[1].value[0]).trim() : null;

if (set != null && set.length) {
  // Nilai yang dikembalikan beda dari yang diminta membuat GenieACS loop commit
  // (fault too_many_commits), jadi penolakan dilakukan dengan melempar error.
  const msg = ext("ont_account", "setPass", ip, "admin", set, "", 2800);
  if (msg !== "OK") throw new Error("Password superadmin gagal diganti: " + msg);
  return { writable: true, value: [set, "xsd:string"] };
}

const raw = ext("ont_account", "get", ip, 1500);
if (!raw) return { writable: true, value: ["[ext tidak mengembalikan data]", "xsd:string"] };

let a = null;
try {
  a = JSON.parse(raw);
} catch (e) {
  return { writable: true, value: ["[respon ext tidak valid]", "xsd:string"] };
}

const val = String(a.adminPass || "");
if (!val.length) return { writable: true, value: ["[Password superadmin tidak terbaca]", "xsd:string"] };
return { writable: true, value: [val, "xsd:string"] };

// Discovery: isi objek vendor X_CT-COM di DeviceInfo (kandidat penampung pengaturan web/captcha).
const now = Date.now();

function names(pattern) {
  const out = [];
  const d = declare(pattern, { value: now });
  if (!d || !d.size) return out;
  for (const e of d) out.push(Array.isArray(e) ? String(e[0]) : String(e.path || ""));
  return out;
}

const kids = names("InternetGatewayDevice.DeviceInfo.X_CT-COM_TeleComAccount.*")
  .concat(names("InternetGatewayDevice.DeviceInfo.X_CT-COM_ServiceManage.*"))
  .concat(names("InternetGatewayDevice.DeviceInfo.X_CT-COM_PortalManagement.*"))
  .concat(names("InternetGatewayDevice.DeviceInfo.X_CT-COM_Monitor.*"))
  .concat(names("InternetGatewayDevice.DeviceInfo.X_CT-COM_Capability.*"))
  .map((k) => k.split(".").slice(3).join("."));

return { writable: false, value: [kids.join("\n").slice(0, 3900) || "(kosong)", "xsd:string"] };

// VP read-only: password WiFi ONT ZTE CL601.
// Firmware mengisi KeyPassphrase kosong lewat TR-069, jadi nilainya diambil dari
// database internal ONT lewat shell (ext ont_zte -> sidbg 1 DB p WLANPSK).
// ext() sengaja tidak dibungkus try/catch: ia melempar simbol agar sesi di-restart.
const now = Date.now();

const pc = declare("InternetGatewayDevice.DeviceInfo.ProductClass", { value: now });
if (!pc || !pc.value || String(pc.value[0]) !== "CL601")
  return { writable: false, value: ["[hanya CL601]", "xsd:string"] };

const url = declare("VirtualParameters.IPTR069", { value: now });
const ip = url && url.value && url.value[0]
  ? String(url.value[0]).replace(/^https?:\/\//, "").replace(/\/.*$/, "")
  : "";

if (!/^[0-9.]+$/.test(ip))
  return { writable: false, value: ["[IP ONT tidak diketahui]", "xsd:string"] };

const raw = ext("ont_zte", "get", ip, 2800);
if (!raw) return { writable: false, value: ["[ext tidak mengembalikan data]", "xsd:string"] };

let d = null;
try {
  d = JSON.parse(raw);
} catch (e) {
  return { writable: false, value: ["[respon ext tidak valid]", "xsd:string"] };
}

const list = (d && d.entries) || [];
const aktif = list.filter((e) => e.enable && e.ssid && e.psk);
const one = aktif.length ? aktif[0] : list.filter((e) => e.psk)[0];

if (!one || !one.psk) return { writable: false, value: ["[password tidak terbaca]", "xsd:string"] };
return { writable: false, value: [String(one.psk), "xsd:string"] };

// VP read-only: ringkasan SSID + password semua WLAN ONT ZTE CL601.
// Sumber sama dengan VirtualParameters.WifiKey (shell ONT, ext ont_zte).
// ext() sengaja tidak dibungkus try/catch: ia melempar simbol agar sesi di-restart.
const now = Date.now();

const pc = declare("InternetGatewayDevice.DeviceInfo.ProductClass", { value: now });
if (!pc || !pc.value || String(pc.value[0]) !== "CL601")
  return { writable: false, value: ["[hanya CL601]", "xsd:string"] };

const url = declare("VirtualParameters.IPTR069", { value: now });
const ip = url && url.value && url.value[0]
  ? String(url.value[0]).replace(/^https?:\/\//, "").replace(/\/.*$/, "")
  : "";

if (!/^[0-9.]+$/.test(ip))
  return { writable: false, value: ["[IP ONT tidak diketahui]", "xsd:string"] };

const raw = ext("ont_zte", "get", ip, 2800);
if (!raw) return { writable: false, value: ["[ext tidak mengembalikan data]", "xsd:string"] };

let d = null;
try {
  d = JSON.parse(raw);
} catch (e) {
  return { writable: false, value: ["[respon ext tidak valid]", "xsd:string"] };
}

const list = (d && d.entries) || [];
const teks = list
  .filter((e) => e.ssid || e.psk)
  .map((e) => e.index + ". " + (e.ssid || "(kosong)") + " = " + (e.psk || "(kosong)") + (e.enable ? "" : " [mati]"))
  .join(" | ");

if (!teks.length) return { writable: false, value: ["[password tidak terbaca]", "xsd:string"] };
return { writable: false, value: [teks, "xsd:string"] };
